import { readFileSync } from 'node:fs';
import { createHash } from 'node:crypto';
import { createRequire } from 'node:module';
import { build } from 'esbuild';
const require=createRequire(process.cwd()+'/package.json');
const entry=[
"export {MemoryWorkspaceRecordStore, CanonicalWorkspaceRepository} from './src/domain/v2/repository.ts'",
"export {SemanticRepository} from './src/experiments/mainline05/semanticRepository.ts'",
"export {completeInputRun} from './src/experiments/mainline05/semanticCapture.ts'",
"export {reviewSemanticFact,confirmSemantic} from './src/experiments/mainline05/semanticConfirmation.ts'",
"export {semanticReview,semanticView,semanticDates} from './src/experiments/mainline05/semanticView.ts'",
"export {stateOfRuntime,semanticRevision,REAL_STATE_VERSION} from './src/experiments/mainline05/semanticState.ts'",
"export {inputRunContext,emptyRealInputWorkspace} from './src/experiments/realInput01/runtime.ts'",
"export {buildModelRequest} from './src/experiments/realInput01/modelWire.ts'",
"export {acquireText} from './src/experiments/realInput01/inputAcquisition.ts'",
"export {makeSendSnapshot} from './src/experiments/realInput01/inputReceipt.ts'",
"export {seenWire,notices,NOW} from './src/experiments/realInput01/seenInputs.ts'",
"export {SemanticFacts} from './src/experiments/mainline05/SemanticFacts.tsx'",
"export {buildBrowserReminderJobs} from './src/lib/notifications.ts'",
"export {calculateTaskPriority} from './src/lib/taskLogic.ts'",
"export {CalendarPage} from './src/pages/CalendarPage.tsx'"
].join(';');
const compiled=await build({stdin:{contents:entry,resolveDir:process.cwd(),loader:'ts'},bundle:true,write:false,format:'cjs',jsx:'automatic',platform:'node',packages:'external',logLevel:'silent',define:{'import.meta.env':'{}'}});
const m={exports:{}};new Function('require','module','exports',compiled.outputFiles[0].text)(require,m,m.exports);
const api=m.exports,{createElement}=require('react'),{renderToStaticMarkup}=require('react-dom/server');
const sha=b=>createHash('sha256').update(b).digest('hex'),json=p=>JSON.parse(readFileSync(p,'utf8')),same=(a,b)=>JSON.stringify(a)===JSON.stringify(b);
let networkCalls=0;globalThis.fetch=async()=>{networkCalls++;throw Error('READONLY_REPLAY_NETWORK_FORBIDDEN')};
const old='docs/recognition-optimization/mainline-real-input-01/runs/usage-resume-20260907a/';
const run='docs/recognition-optimization/mainline-real-input-01/runs/recovery-a02-20260907a/';
const binding=json(old+'STATE.json'),manifest=json(old+'REQUEST_MANIFEST.json'),row=json(run+'RAW_RESULTS.jsonl');
for(const x of [binding.preparation,binding.independentRepositoryRead])if(sha(readFileSync(x.path))!==x.sha256)throw Error('ORIGINAL_ARTIFACT_CHANGED');
const prep=json(binding.preparation.path),record=json(binding.independentRepositoryRead.path),a02=prep.preparations.find(x=>x.unitId==='A02');
if(sha(JSON.stringify(record.workspace))!==binding.independentRepositoryRead.workspaceSha256)throw Error('WORKSPACE_BINDING');
const checks=[];function check(ok,name){checks.push({name,status:ok?'PASS':'FAIL'});if(!ok)throw Error(name)}
async function openCopy(workspace,name){const store=Object.assign(new api.MemoryWorkspaceRecordStore(),{name});await new api.CanonicalWorkspaceRepository(store).save(structuredClone(workspace));const repo=await api.SemanticRepository.open(name,store,undefined,'real-input-01');return{store,repo,name}}
const h=a02.handle,{store,repo,name}=await openCopy(record.workspace,record.name);
const context=await api.inputRunContext(repo,h), request=await api.buildModelRequest(context);
check(sha(request.serialized)===row.requestSha&&sha(a02.requestText)===row.requestSha,'A02_EXACT_REQUEST_BINDING');
check(row.requestSha===manifest.units.find(x=>x.unitId==='A02').requestSha&&sha(row.rawHttpText)===row.responseSha,'RAW_MANIFEST_RESPONSE_BINDING');
const original=await repo.load();
check(original.tasks.length===0,'NO_TASK_BEFORE_COMPLETION');
await api.completeInputRun(repo,h,row.rawHttpText);
const firstWorkspace=await repo.load(),first=api.stateOfRuntime(firstWorkspace,h.draftId);
const firstSnapshot=JSON.stringify({raw:first.rawHttpText,response:first.rawResponse,first:first.first});
const items=api.semanticReview(firstWorkspace,h.draftId),taskId=first.adaptedResponse.tasks[0].id;
check(firstWorkspace.tasks.length===0,'NO_TASK_BEFORE_CONFIRMATION');
check(first.execution==='live'&&first.context.authority==='live_model_candidate'&&first.rawHttpText===row.rawHttpText,'LIVE_ORIGINAL_IDENTITY_PRESERVED');
check(items.draft.items.length===1&&!items.draft.items[0].selected,'NONEMPTY_SUGGESTION_NOT_AUTO_SELECTED');
const prior=JSON.stringify(await repo.load());let refused=null;
try{await api.confirmSemantic(repo,{draftId:h.draftId,taskTempIds:[taskId],revision:api.semanticRevision(await repo.load())})}catch(e){refused=e.message}
check(!!refused&&JSON.stringify(await repo.load())===prior,'UNREVIEWED_CONFIRMATION_REJECTED_ATOMICALLY');
const factsHtml=renderToStaticMarkup(createElement(api.SemanticFacts,{state:first,taskId}));
await api.reviewSemanticFact(repo,{draftId:h.draftId,taskId,revision:api.semanticRevision(await repo.load()),operationId:'readonly-a02-review'});
const reviewed=await repo.load(),selected=api.semanticReview(reviewed,h.draftId,{['draft-item:'+h.draftId+':'+taskId]:true});
check(selected.draft.items[0].selected===true,'EXPLICIT_REVIEW_AND_CHOICE_ALLOWED');
const final=await api.confirmSemantic(repo,{draftId:h.draftId,taskTempIds:[taskId],revision:api.semanticRevision(reviewed)});
check(final.tasks.length===1,'EXPLICIT_CONFIRMATION_CREATES_ONE_TASK');
const finalState=api.stateOfRuntime(final,h.draftId);
check(firstSnapshot===JSON.stringify({raw:finalState.rawHttpText,response:finalState.rawResponse,first:finalState.first}),'RAW_RESPONSE_FIRST_PRESERVED');
check(final.timePoints.length===0&&final.reminderRecords.length===0,'NO_FAKE_DATE_OR_REMINDER');
const reopened=await api.SemanticRepository.open(name,store,undefined,'real-input-01'),loaded=await reopened.load();
check(same(final,loaded),'INDEPENDENT_REPOSITORY_REOPEN_AGREEMENT');
const exported=JSON.parse(await reopened.exportJson());
check(same(JSON.parse(JSON.stringify(loaded)),exported),'MEMORY_JSON_EXPORT_AGREEMENT');
const again=await api.confirmSemantic(reopened,{draftId:h.draftId,taskTempIds:[taskId],revision:api.semanticRevision(loaded)});
check(same(loaded,again),'DUPLICATE_CONFIRMATION_NO_CHANGE');
const view=api.semanticView(loaded),dates=api.semanticDates(loaded),jobs=api.buildBrowserReminderJobs(view.tasks,new Date());
check(jobs.length===0,'ACTUAL_JOBS_FUNCTION_ZERO');
const controlResults=[];
for(const kind of ['no-date','multi','condition-true','revision']){
 const n='rco-mainline-01-02-i1-real-input-readonly-control-'+kind,{repo:c,store:cs}=await openCopy(api.emptyRealInputWorkspace(n,api.NOW),n);
 const receipt=await api.acquireText('readonly-control-'+kind,api.notices[kind]);
 const source=await c.saveReading(receipt,'旧已见人工工程对照','readonly-control-'+kind,api.NOW);
 const handle=await c.beginInputRun(source.sourceId,{version:api.REAL_STATE_VERSION,inputReceipt:receipt,sendSnapshot:await api.makeSendSnapshot(receipt,[1],[1],api.NOW)},'seen_engineering_replay','readonly-control-send-'+kind,api.semanticRevision(await c.load()),api.NOW);
 const response=await api.seenWire(kind,handle);await api.completeInputRun(c,handle,response.rawHttpText);
 const w=await c.load(),s=api.stateOfRuntime(w,handle.draftId),ids=s.first.items.filter(x=>x.requiresAction==='true'&&!x.issues.length).map(x=>x.tempId);
 check(ids.length>0,'CONTROL_NONZERO_'+kind);
 for(const id of ids)await api.reviewSemanticFact(c,{draftId:handle.draftId,taskId:id,revision:api.semanticRevision(await c.load()),operationId:'control-review-'+id});
 const f=await api.confirmSemantic(c,{draftId:handle.draftId,taskTempIds:ids,revision:api.semanticRevision(await c.load())});
 const fresh=await api.SemanticRepository.open(n,cs,undefined,'real-input-01');
 check(f.tasks.length===ids.length&&same(f,await fresh.load()),'CONTROL_CONFIRM_REOPEN_'+kind);
 controlResults.push({kind,selected:ids,confirmed:f.tasks.map(t=>({title:t.title,id:t.id})),execution:s.execution});
}
check(networkCalls===0,'ZERO_NETWORK_EXECUTIONS');

const priority=api.calculateTaskPriority(view.tasks[0],view.tasks,new Date(),dates);
const calendarHtml=renderToStaticMarkup(createElement(api.CalendarPage,{isolatedTimezone:'Asia/Shanghai',dateViews:dates,tasks:view.tasks,events:[],courseBlocks:[],onOpenTask:()=>{},onAddCourseBlock:()=>{},onRemoveCourseBlock:()=>{}}));
check(calendarHtml.includes('无截止日期任务')&&calendarHtml.includes('保存活动手册'),'ACTUAL_CALENDAR_COMPONENT_UNDATED_SSR');
const compactView=value=>({states:value.states,items:value.draft.items.map(i=>({id:i.id,selected:i.selected,status:i.status,suggestion:i.suggestion}))});
const task=Object.fromEntries(Object.entries(loaded.tasks[0]).filter(([k])=>k!=='legacyData'));
const legacyTask=Object.fromEntries(Object.entries(view.tasks[0]).filter(([k])=>!['legacyData','sourceContent'].includes(k)));
console.log(JSON.stringify({version:'a02-readonly-replay-1',artifactBasis:{preparation:binding.preparation,independentRepositoryRead:binding.independentRepositoryRead,unitId:'A02',handle:h,requestSha:row.requestSha,responseSha:row.responseSha},method:'Existing functions and SSR component; cloned exported preparation in MemoryWorkspaceRecordStore; no original/browser database writes',checks,first:{execution:first.execution,authority:first.context.authority,rawResponse:first.rawResponse,firstSha:sha(JSON.stringify(first.first)),issues:first.first.items.map(i=>({id:i.tempId,issues:i.issues,requiresAction:i.requiresAction}))},viewBefore:compactView(items),viewSelected:compactView(selected),unreviewedRejection:refused,component:{htmlSha:sha(factsHtml),visibleBeforeRawDetails:factsHtml.split('<details><summary>原始响应与首次建议')[0],mustProvide:factsHtml.includes('必须提供'),rawNoDateRetained:row.rawHttpText.includes('not_stated')},canonical:{task,materials:loaded.materials,timePoints:loaded.timePoints,reminders:loaded.reminderRecords,evidence:loaded.evidenceRefs.filter(e=>e.sourceId===h.sourceId),operations:finalState.operations,workspaceSha:sha(JSON.stringify(loaded)),sourceCount:loaded.sources.length},downstream:{task:legacyTask,dates,jobs:jobs.length,priority,calendarSsr:{htmlSha:sha(calendarHtml),undatedVisible:calendarHtml.includes('保存活动手册 · 原文未说明截止时间')}},controls:controlResults,sourceRawUnchanged:loaded.sourceVersions.find(v=>v.id===h.sourceVersionId).rawText===a02.context.index.sourceContent,networkCalls,modelCalls:0,actualBrowser:'NOT_RUN',actualDownload:'NOT_RUN',humanActiveTime:'NOT_RUN'}));
